from h import P
R=[
(2482,"Limun Mint (Minted Lemonade)","Hilangkan dahaga Anda dengan segelas Limun Mint yang menyegarkan. Resep ramah ginjal ini menghadirkan keseimbangan yang tepat antara lemon, mint, dan pemanis untuk minuman lezat yang akan Anda nikmati sepanjang musim panas.","5","6 ons (3/4 cangkir)",
["6 sendok makan air jeruk lemon segar","1/2 cangkir gula","6 lembar daun mint","3-1/2 cangkir air dingin"],
["Dalam teko 1 kuart, campurkan air jeruk lemon, gula, dan daun mint. Tambahkan 3-1/2 cangkir air dingin sampai teko penuh.","Dinginkan sampai dingin.","Sajikan dalam gelas 6 ons dengan setangkai mint sebagai hiasan."],
["Untuk rasa mint yang lebih kuat, remas daun mint.","Untuk mengurangi karbohidrat dan kalori, ganti gula dengan pemanis Splenda® (12 sachet atau 1/2 cangkir Splenda® butiran. Kalori berkurang menjadi 16 dan karbohidrat menjadi 4 gram."]),
(2483,"Roti Gulung Lobster Gaya New England","Kunci roti gulung lobster yang enak adalah membuatnya sederhana. Roti bun panggang berisi lobster yang dicampur mayones, air jeruk lemon, seledri, dan saus pedas membuat Roti Gulung Lobster Gaya New England ini istimewa!","4","1 roti gulung lobster",
["12 ons daging lobster","1/3 cangkir seledri","3 sendok makan mayones","3 sendok makan air jeruk lemon","1/4 sendok teh saus pedas","4 roti hotdog dengan belahan atas","2 sendok makan mentega tanpa garam","4 irisan lemon berbentuk baji"],
["Kukus lobster sampai dagingnya buram, sekitar 5 sampai 6 menit. Biarkan dingin lalu potong lobster menjadi potongan seukuran satu gigitan. Cincang halus seledri selagi lobster dimasak.","Campurkan mayones, seledri, air jeruk lemon, dan saus pedas. Tambahkan daging lobster dan aduk hingga terlapisi.","Belah roti bun dan oleskan mentega. Panggang dalam wajan.","Buat roti gulung lobster dengan membagi campuran lobster ke dalam 4 roti bun. Sajikan dengan irisan lemon."],
["Beli roti hotdog biasa jika roti hotdog dengan belahan atas tidak tersedia.","Cari daging lobster segar atau beku atau ekor lobster, atau masak satu lobster utuh. Dua ekor lobster 6 ons sangat cocok.","Daging lobster secara alami tinggi natrium. Pilih makanan lebih rendah natrium untuk waktu makan lainnya agar tetap dalam batas natrium Anda."]),
(2485,"Kue Apel Panggang Dua Kali","Nikmati aroma apel panggang, kayu manis, dan kue dengan Kue Apel Panggang Dua Kali yang ramah ginjal.","12","1/12 potong kue",
["2/3 cangkir gula pasir ditambah 3 sendok makan","1 cangkir tepung terigu serbaguna, tidak diayak","7 sendok makan margarin","1 sendok teh baking soda","1 sendok teh ekstrak vanila","2 butir telur besar","4 buah apel asam besar","1 sendok teh kayu manis bubuk"],
["Panaskan oven terlebih dahulu hingga 350° F. Olesi loyang springform 9 inci dengan lemak.","Potong 4 sendok makan margarin menjadi potongan-potongan. Dengan pisau logam food processor terpasang, masukkan 2/3 cangkir gula, tepung, 4 sendok makan margarin, baking soda, vanila, dan satu butir telur ke dalam mangkuk food processor. Proses sampai campuran menyerupai tepung jagung. Ratakan campuran di dasar loyang yang sudah dioles lemak dengan baik.","Kupas, belah empat, dan buang biji apel. Pasang cakram pengiris pada food processor dan berdirikan potongan apel tegak di dalam saluran pengisian. Iris dengan tekanan sedang pada pendorongnya.","Susun irisan apel berlapis di atas campuran remah. Panggang selama 45 menit.","Selagi kue dipanggang, masukkan sisa 3 sendok makan gula, sisa 3 sendok makan margarin (dilelehkan), kayu manis, dan satu butir telur ke dalam mangkuk food processor dengan pisau logam terpasang. Proses sampai campuran halus dan gula larut. Sendokkan campuran di atas apel dan panggang 30 menit lagi atau sampai bagian atas kencang."],
["Varietas apel yang direkomendasikan meliputi Cortland, Pippin, Rome, atau favorit pribadi Anda.","Jika Anda tidak memiliki food processor, gunakan blender untuk mencampur adonan kue dan topping."]),
(2492,"Roti Perancis Putih Telur Microwave Tanpa Repot","Selagi koki di restoran mewah mungkin dijuluki “kreatif” saat meracik resep, ahli gizi ginjal menggunakan kreativitas yang sama untuk membantu pasien ginjal menikmati diet sehat mereka. Ahli gizi DaVita, Susan dari Oregon, membagikan Roti Perancis Putih Telur Microwave Tanpa Repot yang lezat—sarapan rendah gula dan rendah lemak yang luar biasa, yang juga dapat didinginkan dan dimakan seperti puding roti. Lezat dua kali lipat!","1","1 mangkuk",
["1 iris roti","1 sendok teh mentega tanpa garam, dilunakkan","1/2 cangkir putih telur","2 sendok makan sirup bebas gula"],
["Oleskan mentega pada roti atau English muffin. Potong menjadi dadu.","Letakkan potongan roti berlapis mentega dalam mangkuk yang aman untuk microwave.","Tuang putih telur di atas roti sampai menutupi.","Taburkan sirup di atasnya.","Microwave selama 1 menit; dorong tepi putih telur ke atas agar telur yang belum matang mengalir ke tepi.","Microwave semenit lagi atau sampai telur set."],
["Sajikan hangat sebagai roti Perancis atau dinginkan dan santap sebagai puding roti.","Putih telur menyediakan protein berkualitas sangat baik dengan fosfor atau lemak yang minimal.","Jika diinginkan, ganti 1/2 cangkir putih telur dengan 2 butir telur utuh yang dikocok. Perubahan ini akan menambah nutrisi menjadi 288 kalori, 15 g lemak, 434 mg kolesterol, dan 226 mg fosfor; natrium berkurang menjadi 353 mg.","Jika diinginkan, ganti sirup rendah kalori atau bebas gula dengan sirup maple alami atau gula kayu manis.","Resep ini juga cocok menggunakan setengah English muffin sebagai pengganti seiris roti."]),
(2496,"Challah Klasik","Challah adalah roti ragi sederhana yang disajikan pada hari Sabat dan hari raya Yahudi. Cobalah challah klasik dari Maryam ini.","32","1 potong (2 ons)",
["7 cangkir tepung terigu serbaguna","2 sendok makan ragi kering untuk roti","6 sendok makan gula","2-1/2 cangkir air hangat","1/2 cangkir minyak sayur","2 sendok teh garam","1 butir telur besar"],
["Letakkan tepung, ragi, gula, air, dan minyak dalam mangkuk besar dan campurkan. Uleni adonan. Saat terbentuk bola adonan, tambahkan garam. Letakkan adonan di permukaan yang ditaburi tepung dan lanjutkan menguleni selama 10 menit, sampai adonan halus, lembut, dan tidak lengket.","Olesi mangkuk dan adonan dengan 1 sampai 2 sendok teh minyak. Tutup mangkuk dan letakkan di tempat hangat sampai adonan mengembang dua kali lipat (1 sampai 2 jam).","Uleni adonan yang sudah mengembang selama beberapa menit. Bagi adonan menjadi 12 bagian dan gulung setiap bagian menjadi untaian yang akan dikepang, panjangnya sekitar 10″ sampai 12″.","Kepang 3 untaian adonan yang sudah digulung menjadi satu untuk membentuk challah. Ulangi dengan untaian adonan yang tersisa untuk membuat 4 challah.","Letakkan challah di atas loyang atau dalam wadah pemanggang, tutup dan biarkan adonan mengembang lagi, sekitar 40 menit.","Panaskan oven terlebih dahulu hingga 350º F. Olesi setiap challah dengan telur kocok. Panggang sekitar 30 menit, sampai challah berwarna cokelat keemasan. Angkat challah dari oven dan dari loyang, lalu dinginkan di atas rak kawat."],
["Bagi setiap challah menjadi 8 porsi sehingga total 32 porsi untuk 4 roti.","Taburkan biji poppy atau wijen di atasnya sebelum dipanggang jika diinginkan.","Cari video daring di YouTube untuk petunjuk cara mengepang dan membentuk challah."]),
(2498,"Roti Soda Pop","Roti Soda Pop bukanlah roti cepat saji biasa. Resep ini menggunakan soda yang dicampur dengan cita rasa gurih untuk menciptakan roti unik yang pasti membuat lidah Anda \"meletup\".","12","1 potong",
["3 cangkir tepung terigu serbaguna","1/2 cangkir gula pasir","2 sendok teh baking powder","1/4 sendok teh garam","2 butir telur besar","1 sendok makan bawang putih cincang halus","12 ons root beer","1 sendok teh cabai cayenne"],
["Panaskan oven terlebih dahulu hingga 350˚ F.","Dalam mangkuk sedang, campurkan tepung, gula, baking powder, dan garam. Aduk rata.","Tambahkan telur dan bawang putih lalu aduk. Tambahkan root beer dan cayenne. Aduk semua bahan hingga tercampur rata.","Tuang campuran ke dalam loyang roti 9 x 5 inci yang sudah diolesi lemak.","Panggang selama 55 sampai 65 menit. Biarkan roti dingin sebelum dikeluarkan dari loyang."],
["Gunakan lebih sedikit cabai cayenne jika Anda tidak suka pedas.","Sebagai pengganti root beer dan cayenne, cobalah salah satu variasi berikut: 12 ons ginger ale dan 1/3 cangkir daun rosemary segar cincang; atau 12 ons soda Orange Crush® atau Orange Sunkist® dengan 1 sendok makan kemangi bubuk; atau 12 ons soda lemon-jeruk nipis dengan 1/2 cangkir cilantro segar cincang.","Root beer, ginger ale, soda jeruk, dan soda lemon-jeruk nipis umumnya tidak mengandung tambahan fosfor. Namun, selalu periksa daftar bahan untuk tambahan fosfat."]),
(2499,"Roti Perancis Isi","Ubah sisa roti Prancis menjadi hidangan sarapan lezat yang ramah ginjal, Roti Perancis Isi, yang dapat Anda buat pada malam sebelumnya lalu cukup dimasukkan ke dalam oven di pagi hari.","8","1/8 resep",
["8 ons krim keju","1 pon roti Prancis satu loyang, sehari sebelumnya","8 sendok makan selai jeli, rasa apa saja","6 butir telur besar","1 cangkir susu rendah lemak 1%","1 sendok teh ekstrak vanila"],
["Potong roti menjadi 16 iris.","Oleskan 1 sendok makan krim keju pada setiap iris roti. Beri topping 1 sendok makan selai jeli dan tambahkan iris roti lain untuk membuat sandwich. Ulangi sampai terbentuk 8 sandwich.","Semprot wadah pemanggang 9” x 13” dengan semprotan masak antilengket dan letakkan 8 sandwich di dalamnya.","Kocok telur lalu campurkan dengan susu dan ekstrak vanila. Tuang di atas irisan roti, balikkan agar irisan terlapisi merata. Tutup dan simpan di lemari es semalaman.","Panaskan oven terlebih dahulu hingga 350° F. Tutup loyang dengan foil dan panggang selama 1 jam. Pada 5 menit terakhir pemanggangan, buka foil agar bagian atas kecokelatan."],
["Biarkan krim keju mencapai suhu ruangan agar lebih mudah dioleskan.","Saran penyajian: siram dengan sirup, hias dengan buah segar dan krim kocok, atau taburi gula bubuk.","Resep ini merupakan sumber protein dan kalori yang baik, pilihan bagus untuk sarapan berenergi tinggi. Cobalah variasi lain dari roti Perancis ini. Cocok untuk memanfaatkan sisa roti. Selain itu, menyiapkan resep ini pada malam sebelumnya membuat Anda tidak perlu melakukan apa-apa lagi di pagi hari kecuali memanggang dan menyajikannya. Sempurna untuk brunch.","Bandingkan roti dan pilih merek dengan natrium lebih rendah."]),
(2500,"Strawberry Fields Forever","Strawberry Fields Forever bukan hanya judul lagu The Beatles, tetapi juga hidangan stroberi yang menyegarkan yang dibagikan oleh ahli gizi ginjal DaVita, Sandee dari California. Resep ramah ginjal Strawberry Fields Forever dari Sandee memadukan rasa manis buah segar dengan cuka balsamik yang gurih. Ini adalah resep mudah yang dapat dinikmati sendiri, atau menjadi topping yang menyenangkan pada salad, kue, atau camilan beku.","4","1/2 cangkir",
["3 cangkir stroberi segar","2 sendok makan cuka balsamik","2 sendok makan pemanis tanpa kalori Splenda®, butiran","1/4 sendok teh lada hitam yang baru digiling"],
["Cuci stroberi beserta kelopaknya (jika tidak, air akan meresap ke bagian tengah sehingga stroberi menjadi lembek).","Lepaskan kelopak dengan pisau kecil.","Potong stroberi menjadi dua.","Letakkan stroberi dalam mangkuk, siram dengan cuka, dan taburi dengan Splenda®.","Aduk perlahan sampai tercampur.","Tutup dan simpan di lemari es selama beberapa jam, sebaiknya semalaman.","Sesaat sebelum disajikan, gilingkan lada di atas stroberi."],
["Keluarkan stroberi dari lemari es 10 menit sebelum disajikan untuk menghilangkan rasa dinginnya.","Dapat disajikan sebagai topping pada kue angel food.","Jika diinginkan, gunakan gula atau pemanis meja lainnya sebagai pengganti Splenda®."]),
(2502,"Kue Apel Segar dengan Frosting Krim Keju","Apel, kayu manis, pekan, dan krim keju semuanya dipadukan dalam kue lezat yang ramah ginjal berkat Bev dan ahli gizi ginjal Nancy dari California. Sajikan sebagai hidangan penutup sehari-hari atau pada acara istimewa. Tamu Anda tidak akan pernah menyangka ini adalah kue rendah natrium, rendah kalium, dan rendah fosfor.","20","2-1/4\" x 2-1/2\"",
["2 butir telur besar","3/4 cangkir minyak canola","2 cangkir gula pasir","3 sendok teh vanila","4 buah apel sedang","2 cangkir tepung terigu serbaguna","2 sendok teh kayu manis","2 sendok teh baking soda","1 cangkir pekan cincang","8 ons krim keju","2 cangkir gula bubuk"],
["Panaskan oven terlebih dahulu hingga 350º F. Semprot loyang 9″ x 13″ dengan semprotan masak antilengket.","Keluarkan krim keju agar lunak. Kupas, buang bijinya, dan cincang apel.","Campurkan telur, minyak, gula, dan 2 sendok teh vanila. Aduk dengan apel.","Dalam mangkuk terpisah, aduk tepung, kayu manis, baking soda, dan pekan.","Tambahkan campuran kering ke campuran apel dan aduk bersama.","Masukkan ke dalam loyang dan panggang selama satu jam. Biarkan dingin.","Untuk lapisan gula, gunakan mixer untuk mencampur krim keju, gula bubuk, dan sisa vanila.","Oleskan lapisan gula di atas kue setelah dingin."],
["Bagi penderita diabetes, jangan gunakan lapisan gula untuk mengurangi kalori menjadi 252 dan karbohidrat menjadi 33 g. Hitung sebagai 2 pilihan karbohidrat.","Untuk mengurangi lemak, Anda dapat mengganti setengah minyak dengan saus apel tanpa pemanis.","Pekan tinggi kalium dan fosfor. Jumlah yang disumbangkan pada satu potong kue minimal selama porsi yang dianjurkan diikuti. Jika tidak, Anda dapat menguranginya menjadi 1/2 cangkir pekan atau tidak menggunakannya."]),
(2503,"Pasta Primavera Krimi","Ahli gizi ginjal DaVita, Mary dari California, senang mencoba berbagai hidangan etnis dan membuatnya ramah ginjal agar pasien dialisisnya juga dapat menyantapnya. Jika Anda menyukai masakan Italia, cobalah Pasta Primavera Krimi dari Mary.","6","1 cangkir",
["1 cangkir wortel","8 ons krim keju","1/4 cangkir daun bawang","8 ons pasta dasi kupu-kupu gandum utuh, mentah","1 cangkir kuntum brokoli","3/4 cangkir minuman beras Rice Dream® Original Classic","2 sendok makan keju Parmesan parut","1 sendok teh bumbu Italia","1/4 sendok teh bubuk bawang putih"],
["Iris wortel, cincang daun bawang, dan potong dadu krim keju.","Masak pasta sesuai petunjuk kemasan (tanpa garam). Pada 5 menit terakhir waktu memasak, tambahkan brokoli dan wortel ke dalam air. Tiriskan.","Campurkan krim keju, Rice Dream®, keju Parmesan, bawang, dan bumbu dalam panci besar; masak dengan api kecil sampai krim keju meleleh dan campuran tercampur baik, sering diaduk.","Campurkan pasta dan sayuran; aduk perlahan dan sajikan panas."],
["Untuk hidangan yang lebih tinggi protein, tambahkan ayam atau udang.","Brokoli dan wortel beku dapat digunakan sebagai pengganti sayuran segar.","Susu beras yang diperkaya mengandung tambahan fosfor dan kalsium. Cari produk yang tidak diperkaya."]),
(2505,"Wrap Sayuran Roti Pipih dengan Hummus Buatan Sendiri","Wrap ini menghadirkan sayuran yang indah bersama hummus buatan sendiri yang unik dan mudah. Pasti menjadi resep favorit baru.","2","1 wrap",
["1/4 cangkir bawang bombai merah","2 buah tomat ceri","1/2 buah paprika sedang","1/2 buah wortel besar","1 siung bawang putih","2 roti pipih Yunani","1 sendok makan yoghurt Yunani tawar","1/2 sendok teh lada hitam bubuk","1 sendok makan minyak zaitun","1 sendok makan tahini","1 sendok makan air jeruk lemon","1/2 sendok teh jintan bubuk","1/2 sendok teh bubuk bawang putih","1/4 cangkir bayam muda segar","1 sendok makan keju feta remah"],
["Iris bawang bombai merah dan potong tomat ceri menjadi empat bagian. Iris paprika merah dan wortel menjadi potongan tipis memanjang. Cincang halus siung bawang putih.","Panaskan roti pipih satu per satu dalam wajan panas dengan api sedang, 3-4 menit per sisi.","Kocok bawang putih cincang, yoghurt Yunani tawar, lada hitam bubuk, minyak zaitun, tahini, air jeruk lemon, jintan bubuk, dan bubuk bawang putih dalam mangkuk.","Oleskan saus secara merata di setiap roti pita.","Susun bawang bombai, tomat, paprika, wortel, dan bayam di atas setiap roti pipih, dibagi rata untuk kedua roti pipih.","Taburkan feta di atas sayuran dan lipat atau gulung roti pipih mengelilingi sayuran."],
["Jika roti pipih Yunani tidak tersedia, jenis roti pipih lain dapat digunakan sebagai pengganti. Lihat label makanan untuk merek dengan kadar natrium terendah dan kadar karbohidrat terendah jika Anda menjalani diet karbohidrat lebih rendah.","Gunakan sisa yoghurt Yunani sebagai saus celup atau sebagai pengganti krim asam. Sisa wortel dan paprika dapat dicelup ke dalam yoghurt Yunani sebagai camilan."]),
(2507,"Salad Timun dan Wortel","Salad Timun dan Wortel adalah resep yang sejuk, renyah, dan ramah ginjal dari bagian Salad di DaVita.com.","4","1/2 cangkir",
["1/4 cangkir cuka beras tanpa bumbu","1 sendok teh gula","1/2 sendok teh minyak zaitun","1/8 sendok teh lada hitam","1/2 buah timun","1 cangkir wortel","2 sendok makan daun bawang","2 sendok makan paprika merah","1/2 sendok teh campuran bumbu Mrs. Dash® Italian Medley"],
["Campurkan cuka beras, gula, minyak zaitun, dan lada hitam dalam mangkuk sedang. Aduk dengan pengocok.","Belah 1/2 timun menjadi dua secara vertikal, buang bijinya, lalu iris. Iris wortel dan daun bawang. Cincang halus paprika.","Tambahkan wortel, bawang, paprika merah, timun, dan Mrs. Dash ke campuran cuka; aduk hingga terlapisi.","Tutup dan dinginkan 30 menit."],
["Pilih cuka beras tanpa bumbu atau gunakan cuka apel jika tidak tersedia. Hindari cuka beras berbumbu, karena mengandung 240 miligram natrium hanya dalam satu sendok makan."]),
(2508,"Cincin Apel Goreng Tepung","Siapa yang tidak suka Apple Fritter? Nikmati Cincin Apel Goreng Tepung (Apple Fritter) yang ramah ginjal saat Anda membuat sarapan berikutnya.","20","1 fritter",
["4 buah apel masak asam besar","1 cangkir tepung terigu putih serbaguna","6 sendok makan gula (dibagi)","1 sendok teh baking powder","1 butir telur besar, dikocok","1/3 cangkir susu rendah lemak 1%","1/3 cangkir susu almond","1 sendok teh minyak canola","Minyak untuk menggoreng rendam, sekitar 3/4 cangkir","1/2 sendok teh kayu manis"],
["Kupas dan buang bagian tengah apel. Potong setiap apel menjadi 5 cincin, masing-masing setebal sekitar 1/2″.","Dalam mangkuk pencampur, ayak tepung, 2 sendok makan gula, dan baking powder.","Dalam mangkuk terpisah, campurkan telur, susu, susu almond, dan 1 sendok teh minyak.","Tambahkan campuran telur ke bahan kering dan aduk sampai baru tercampur.","Dalam wajan dengan kedalaman minimal 2″, panaskan 1″ minyak goreng hingga 375º F.","Celupkan irisan apel ke dalam adonan satu per satu. Goreng dalam minyak panas sekitar 1-1/2 menit sampai cokelat keemasan. Tiriskan di atas tisu dapur.","Campurkan sisa 1/4 cangkir gula dengan kayu manis dan taburkan di atas fritter. Sajikan panas."],
["Apple fritter dari toko donat mengandung sekitar 300 mg natrium dibandingkan 33 mg per fritter dalam resep ini.","Pengganti gula butiran Splenda® dapat digunakan sebagai pengganti gula, jika diinginkan."]),
(2509,"Sosis Kalkun Buatan Sendiri","Nikmati Sosis Kalkun Buatan Sendiri untuk sarapan ramah ginjal Anda berikutnya.","12","1 patty",
["1 sendok teh biji adas","1 pon daging kalkun giling, lemak 7%","1/8 sendok teh bubuk bawang putih","1/8 sendok teh bubuk bawang bombai","1/4 sendok teh garam"],
["Tumbuk biji adas.","Dalam mangkuk kecil, campurkan kalkun dengan biji adas tumbuk, bubuk bawang putih, bubuk bawang bombai, dan garam. Tutup mangkuk dan simpan di lemari es semalaman.","Bagi kalkun berbumbu menjadi porsi seukuran bola pingpong dan pipihkan menjadi patty untuk dimasak.","Masak dengan api sedang dalam wajan antilengket sampai kecokelatan, sekitar 1 sampai 2 menit per sisi."],
["Patty ekstra dapat dibekukan untuk digunakan nanti. Pastikan untuk meletakkan lapisan ganda plastik pembungkus atau kertas lilin di antara porsi agar patty mudah dipisahkan."]),
(2511,"Salad Ayam Kari dengan Buah","Seorang ahli gizi DaVita memperkenalkan resep lezat, sederhana, dan ramah ginjal yang memuaskan selera apa pun. Salad Ayam Kari dengan Buah adalah hidangan segar yang memadukan manisnya buah alami dengan rempah-rempah yang gurih.","8","1 cangkir",
["4 dada ayam matang tanpa kulit dan tanpa tulang","1 batang seledri","1/2 cangkir bawang bombai","1 buah apel sedang","1/4 cangkir anggur merah tanpa biji","1/4 cangkir anggur hijau tanpa biji","1/2 cangkir kastanye air kalengan","1/8 sendok teh lada hitam","1/2 sendok teh bubuk kari","3/4 cangkir mayones"],
["Potong dadu ayam. Cincang seledri, bawang bombai, dan apel. Tiriskan dan cincang kastanye air.","Dalam mangkuk salad besar, campurkan ayam, seledri, bawang bombai, apel, anggur, kastanye air, lada, bubuk kari, dan mayones.","Aduk semuanya hingga tercampur.","Sajikan segera atau dinginkan untuk nanti."],
["Untuk menghemat waktu, gunakan setengah ayam rotisserie yang kulit dan tulangnya sudah dibuang."]),
]
P(6,R)
